  ?show a tv:TelevisionShow ;
        tv:country "United Kingdom" ;
        tv:hasGuest <http://example.org/Paul_Melba> ;
        tv:host ?host .
  ?host tv:totalHostedShows ?numShows .
  FILTER(?numShows = 23)
}

