SELECT ?series ?seriesLabel ?actress ?actressLabel WHERE {
  ?series wdt:P57 wd:Q108895839;  # creator Hilarie Ross Burton (assumed QID; if not known, "Hilarie Ross Burton")
          wdt:P449 wd:Q36530.      # broadcast network: The WB Television Network
  ?series wdt:P161 ?actress.      # cast member
  ?actress wdt:P463 wd:Q14262334. # member of the movie "Grace, Replaced"
  ?actress wdt:P1344 ?series.     # actress has role in series (P1344 property for "participant in work" or similar)
  # or use qualifiers for recurring role if available
  # alternatively check with ?series wdt:P161 ?actress and check the role type
  FILTER EXISTS {
    ?series p:P161 ?castStatement.
    ?castStatement ps:P161 ?actress.
    ?castStatement pq:P453 wd:Q422754. # "recurring role" role type
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?profession WHERE {
  ?song wdt:P31 wd:Q7366;
        rdfs:label "Rebuild"@en;
        wdt:P175 ?person.
  ?person wdt:P136 wd:Q180085;  # member of Relient K
           wdt:P106 ?profession.
  FILTER(CONTAINS(LCASE(STR(?person)), "relient_k"))
}
UNION
{
  ?person2 wdt:P31 wd:Q5;
           rdfs:label "George Thorogood"@en;
           wdt:P106 ?profession2.
}

FILTER(STR(?profession) = "musician" && STR(?profession2) = "musician")

SELECT ?person ?profession WHERE {
  ?song wdt:P31 wd:Q7366;
        rdfs:label "Rebuild"@en;
        wdt:P175 ?person.
  ?person wdt:P136 wd:Q180085;  # member of Relient K
           wdt:P106 ?profession.
  FILTER(CONTAINS(LCASE(STR(?person)), "relient_k"))
}
UNION
{
  ?person2 wdt:P31 wd:Q5;
           rdfs:label "George Thorogood"@en;
           wdt:P106 ?profession2.
}

FILTER(STR(?profession) = "musician" && STR(?profession2) = "musician")

SELECT ?mattLabel ?jonLabel ?georgeLabel WHERE {
  ?matt dbo:band <http://dbpedia.org/resource/Relient_K> ;
        dbo:occupation <http://dbpedia.org/resource/Musician> ;
        rdfs:label ?mattLabel .
  FILTER(LANG(?mattLabel) = "en")
  ?jon dbo:band <http://dbpedia.org/resource/Switchfoot> ;
       dbo:occupation <http://dbpedia.org/resource/Musician> ;
       rdfs:label ?jonLabel .
  FILTER(LANG(?jonLabel) = "en")
  ?song dbo:writer ?matt ;
        dbo:writer ?jon ;
        rdfs:label "Rebuild"@en .
  ?george dbo:occupation <http://dbpedia.org/resource/Musician> ;
          rdfs:label ?georgeLabel .
  FILTER(?georgeLabel = "George Thorogood"@en)
}

SELECT ?officeActor ?dealDirector WHERE {
  ?officeMovie rdf:type dbo:Film ;
               rdfs:label "Office"@en ;
               dbo:starring ?officeActorRole1, ?officeActorRole2 .
  ?officeActorRole1 foaf:name "Go Ah-sung"@en .
  ?officeActorRole2 foaf:name ?officeActor .
  FILTER (?officeActor != "Go Ah-sung"@en)

  ?dealMovie rdf:type dbo:Film ;
             rdfs:label "The Deal"@en ;
             dbo:starring ?officeActor ;
             dbo:director ?dealDirectorResource .
  ?dealDirectorResource foaf:name ?dealDirector .
  FILTER (LANG(?dealDirector) = "en")
}

SELECT ?actorName ?directorName WHERE {
  ?officeFilm rdf:type dbo:Film ;
              rdfs:label "Office"@en ;
              dbo:starring ?goAhSung, ?actor .
  ?goAhSung foaf:name "Go Ah-sung"@en .
  ?actor foaf:name ?actorName .
  FILTER(?actorName != "Go Ah-sung")
  ?dealFilm rdf:type dbo:Film ;
            rdfs:label "The Deal"@en ;
            dbo:starring ?actor .
  ?dealFilm dbo:director ?director .
  ?director foaf:name ?directorName .
  FILTER(langMatches(lang(?directorName), "en"))
}

SELECT DISTINCT ?actor ?actorName ?filmOffice ?filmDeal ?director ?directorName WHERE {
  # Films
  ?filmOffice rdfs:label "Office"@en ;
              dbo:starring ?actor, ?coStar .
  ?coStar rdfs:label "Go Ah-sung"@en .
  ?filmDeal rdfs:label "The Deal"@en ;
            dbo:starring ?actor ;
            dbo:director ?director .
  # Actor and director labels
  ?actor rdfs:label ?actorName .
  ?director rdfs:label ?directorName .
  FILTER (LANG(?actorName) = "en")
  FILTER (LANG(?directorName) = "en")
}

SELECT DISTINCT ?film ?filmReleaseDate WHERE {
  ?sacredPlanet rdf:type dbo:Film ;
                rdfs:label "Sacred Planet"@en ;
                dbo:releaseDate ?sacredPlanetDate .
  ?film dbo:releaseDate ?filmReleaseDate ;
        dbo:starring ?actor .
  ?actor rdfs:label "Damion Poitier"@en .
  FILTER(?filmReleaseDate < ?sacredPlanetDate)
}
ORDER BY DESC(?filmReleaseDate)
LIMIT 1

SELECT DISTINCT ?film ?filmReleaseDate WHERE {
  ?sacredPlanet rdf:type dbo:Film ;
                rdfs:label "Sacred Planet"@en ;
                dbo:releaseDate ?sacredPlanetDate .
  ?film dbo:releaseDate ?filmReleaseDate ;
        dbo:starring ?actor .
  ?actor rdfs:label "Damion Poitier"@en .
  FILTER(?filmReleaseDate < ?sacredPlanetDate)
}
ORDER BY DESC(?filmReleaseDate)
LIMIT 1

SELECT ?otherFilm ?otherFilmReleaseDate ?sacredPlanetReleaseDate ?damionPoitierAwards WHERE {
  ?sacredPlanet a dbo:Film ;
                foaf:name "Sacred Planet"@en ;
                dbo:releaseDate ?sacredPlanetReleaseDate .

  ?otherFilm a dbo:Film ;
             dbo:starring ?damionPoitier ;
             dbo:releaseDate ?otherFilmReleaseDate .

  ?damionPoitier a dbo:Actor ;
                foaf:name "Damion Poitier"@en .

  FILTER (?otherFilmReleaseDate < ?sacredPlanetReleaseDate)

  OPTIONAL {
    ?damionPoitier dbo:award ?damionPoitierAwards .
  }
}
ORDER BY ?otherFilmReleaseDate
LIMIT 10

SELECT ?sacredPlanetReleaseDate ?hunterPreyReleaseDate ?poitierRole ?poitierAwards WHERE {
  ?sacredPlanet dbo:title "Sacred Planet"@en .
  ?sacredPlanet dbo:releaseDate ?sacredPlanetReleaseDate .
  ?hunterPrey dbo:title "Hunter Prey"@en .
  ?hunterPrey dbo:releaseDate ?hunterPreyReleaseDate .
  ?hunterPrey dbo:starring ?damionPoitier .
  ?damionPoitier foaf:name "Damion Poitier" .
  OPTIONAL {
    ?damionPoitier dbo:role ?poitierRole .
    ?damionPoitier dbo:award ?poitierAwards .
  }
  FILTER(xsd:date(?sacredPlanetReleaseDate) > xsd:date(?hunterPreyReleaseDate))
}

SELECT ?filmTitle ?releaseDate ?actor WHERE {
  VALUES ?filmTitle {"Hunter Prey" "Sacred Planet"}
  ?film rdf:type dbo:Film .
  ?film rdfs:label ?filmTitle .
  ?film dbo:releaseDate ?releaseDate .
  OPTIONAL {
    ?film dbo:starring ?actorResource .
    ?actorResource rdfs:label ?actor .
    FILTER(CONTAINS(LCASE(?actor), "damion poitier"))
  }
} ORDER BY ?releaseDate

SELECT ?movie ?releaseDate ?writer ?actor ?series ?seriesPremiereDate WHERE {
  ?movie dbo:writer ?writer ;
         dbo:releaseDate ?releaseDate ;
         dbo:starring ?actor .
  ?writer foaf:name "Christopher B. Landon"@en .
  FILTER(YEAR(?releaseDate) = 2007)
  ?actor foaf:name ?actorName .
  FILTER(CONTAINS(LCASE(?actorName), "shia") && CONTAINS(LCASE(?actorName), "laBeouf"))

  ?actor dbo:starring ?series .
  ?series foaf:name "Even Stevens"@en ;
          dbo:releaseDate ?seriesPremiereDate .
  FILTER(YEAR(?seriesPremiereDate) = 2004)
}
LIMIT 10

SELECT ?publication ?publicationFrequency ?bookmarksFrequency ?hallOfFameInductee ?inductionYear WHERE {
  VALUES ?hallOfFameInductee { "Keith Moon" }
  ?publication dbo:hasHallOfFame true .
  ?publication dbo:publicationFrequency ?publicationFrequency .
  ?bookmarks dbo:name "Bookmarks" ;
             dbo:publicationFrequency ?bookmarksFrequency .
  ?publication dbo:hallOfFameInductee ?hallOfFameInductee ;
               dbo:hallOfFameInductionYear ?inductionYear .
  FILTER(?inductionYear >= 1980 && ?inductionYear <= 1989)
  FILTER(?publicationFrequency > ?bookmarksFrequency)
} LIMIT 1

