SELECT ?taxon ?taxonRank ?speciesCount WHERE {
  VALUES ?taxonName {"Caesalpinioideae" "Caesalpinia" "Achimenes"}
  ?taxon rdfs:label ?taxonName.
  ?taxon taxonRank ?taxonRank.
  OPTIONAL {
    ?taxon speciesCount ?speciesCount.
  }
}

SELECT ?taxon ?taxonRank ?speciesCount WHERE {
  VALUES ?taxonName {"Caesalpinioideae" "Achimenes"}
  ?taxon rdfs:label ?taxonName FILTER (lang(?taxonName) = "en").
  ?taxon wdt:P105 ?taxonRankNode.
  ?taxonRankNode rdfs:label ?taxonRank.
  OPTIONAL {
    ?taxon wdt:P2258 ?speciesCount.
  }
}
LIMIT 10

SELECT ?kerberBirthplace ?kerberSport ?defendingChampion ?defendingChampionSport WHERE {
  ?kerber wdt:P31 wd:Q5;        # instance of human
         rdfs:label "Angelique Kerber"@en;
         wdt:P19 ?kerberBirthplace;
         wdt:P641 ?kerberSport.

  # Check if Angelique Kerber's birthplace is in Texas
  ?kerberBirthplace wdt:P131* wd:Q1438 . # Q1438 = Texas

  # Find defending champion for 2005 China Open – Men's Doubles
  wd:Q18878466 wdt:P1346 ?defendingChampion. # Q18878466 = 2005 China Open – Men's Doubles
  ?defendingChampion wdt:P641 ?defendingChampionSport.

  FILTER ( ?kerberSport = wd:Q8470 )      # Tennis sport (Q8470)
  FILTER ( ?defendingChampionSport = wd:Q8470 )
} LIMIT 10

SELECT 
  ?sportKerber ?sportChampion WHERE {
    ?kerber dbo:birthPlace dbr:Texas .
    ?kerber dbo:profession dbr:Tennis_player .
    ?event dbo:year "2005"^^xsd:gYear ;
           dbo:location dbr:China ;
           dbo:eventName "China Open – Men's Doubles" ;
           dbo:sport ?sportChampion .
    ?defendingChampion dbo:champion ?event .
    ?defendingChampion dbo:profession ?sportChampion .
    ?kerber dbo:sport ?sportKerber .
    FILTER (?sportKerber = ?sportChampion)
  }

